import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int B,
    const int C,
    const int H,
    const int W)
{
    // Each block handles one batch element. Only the first thread in each block does the work.
    int b = blockIdx.x;
    if (b < B && threadIdx.x == 0) {
        // We'll store the per-channel means (C <= 1024 in this example).
        // For simplicity, we assume C <= 1024.
        __shared__ float channel_vals[1024];

        // Compute the global average for each channel, then add bias.
        for (int c = 0; c < C; c++) {
            float sum_val = 0.0f;
            // Accumulate across spatial dims
            for (int h = 0; h < H; h++) {
                for (int w = 0; w < W; w++) {
                    int idx = b * C * H * W + c * H * W + h * W + w;
                    sum_val += x[idx];
                }
            }
            float mean_val = sum_val / (float)(H * W);
            channel_vals[c] = mean_val + bias[c];
        }

        // Compute log-sum-exp over channels
        // First find max
        float max_val = -CUDART_INF_F;
        for (int c = 0; c < C; c++) {
            if (channel_vals[c] > max_val) {
                max_val = channel_vals[c];
            }
        }
        // Then compute sum of exp
        float sum_exp = 0.0f;
        for (int c = 0; c < C; c++) {
            sum_exp += expf(channel_vals[c] - max_val);
        }
        float lse = logf(sum_exp) + max_val;

        // Multiply by 10.0, final output for this batch
        out[b] = lse * 10.0f;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias) {
    // x shape: (B, C, H, W)
    // bias shape: (C, 1, 1)
    // Output shape: (B)
    TORCH_CHECK(x.dim() == 4, "x must be a 4D tensor");
    TORCH_CHECK(bias.dim() == 3, "bias must be a 3D tensor [C,1,1]");

    int B = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    // Prepare output
    auto out = torch::zeros({B}, x.options());

    // Launch kernel
    dim3 grid(B);
    dim3 block(1);
    fused_ops_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, H, W
    );
    return out;
}
"""

fused_ops_cpp_source = r"""
torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias);
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that uses a custom CUDA kernel to fuse operations after the ConvTranspose2d.
    """
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)  # (B, C, H, W)
        # Use fused custom kernel to do global average pooling + bias + log-sum-exp + sum + multiply
        out = self.fused_ops.fused_ops_cuda(x, self.bias)
        # Shape is (B,); reshaping to (B, 1) to match original final shape
        return out.unsqueeze(1)

